<script module lang="ts">
/**
 * The mandatory message for a view with nothing to show (`design/components/empty-state.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/empty-state.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { type Snippet } from 'svelte'

import { Icon, joinSlot, type IconRole } from '@polymorph/svelte'
import styles from '@polymorph/recipes/structure/empty-state.module.css'
import Inline from '../layout/Inline.svelte'

export interface EmptyStateProps {
  /**
   * One Button, `soft`/`accent` by convention, so the page's own primary stays primary.
   */
  action?: Snippet
  /**
   * What to do about it.
   */
  description?: string
  icon?: IconRole
  /**
   * A `ghost` Button, such as "Clear filters".
   */
  secondaryAction?: Snippet
  /**
   * Describes the situation, such as "No tickets yet" rather than "Empty".
   */
  title: string
}
</script>

<script lang="ts">
let { action, description, icon = 'inbox', secondaryAction, title }: EmptyStateProps = $props()
const joined = joinSlot(undefined, () => ({}))
const slots = {
  get action() {
    return action
  },
  get secondaryAction() {
    return secondaryAction
  },
}
</script>

{@render joined.start?.()
}{#if joined.shown
  }<div class={styles.empty} data-member="empty-state"
    ><span class={styles.well}><Icon name={icon} size="lg" /></span
    ><h2 class={styles.title}>{title}</h2
    >{#if description !== undefined}<p class={styles.description}>{description}</p>{/if
    }{#if slots.action || slots.secondaryAction
      }<div class={styles.actions}
        ><Inline gap={3} wrap={true} justify="center"
          >{@render action?.()
          }{@render secondaryAction?.()
        }</Inline
      ></div
    >{/if
  }</div
>{/if
}{@render joined.end?.()}
